// Validate AI Agent output before posting to Mattermost.
// If the agent returned nothing, only whitespace, or a non-string value,
// substitute a fallback message so the user always receives a reply.

const data = $input.first().json;
const rawOutput = data.output;
const output = (typeof rawOutput === 'string' ? rawOutput : '').trim();

const FALLBACK = 'Could not complete the investigation.';
const finalOutput = output.length > 0 ? output : FALLBACK;

if (output.length === 0) {
  console.warn('AI Agent returned empty output, using fallback message');
}

return [{ json: { ...data, output: finalOutput, is_fallback: output.length === 0 } }];

// Read the classification object passed from devopsChatAssistant
// Available fields: message, post_id, channel_id, user_name, user_id,
// team_domain, channel_name, timestamp, category, confidence, summary

const data = $input.first().json;

// Log for debugging
console.log(`Incident received: ${data.summary}`);
console.log(`From: ${data.user_name} in #${data.channel_name}`);
console.log(`Confidence: ${data.confidence}`);

return [{ json: data }];
